"use client";
import { CheckCircleIcon, StarIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import NumberFlow from "@number-flow/react";
import { AnimatePresence, motion } from "motion/react";
import React from "react";
import { Button } from "@/components/ui/button";
import { type FREQUENCY, FrequencyToggle } from "./pricing-frequency-toggle-switch";

type Plan = {
	name: string;
	info: string;
	price: {
		monthly: number;
		yearly: number; // yearly per month
	};
	features: string[];
	btn: {
		text: string;
		href: string;
	};
	highlighted?: boolean;
};

const plans: Plan[] = [
	{
		name: "Basic",
		info: "For most individuals",
		price: {
			monthly: 7,
			yearly: 6,
		},
		features: [
			"Up to 3 Blog posts",
			"Up to 3 Transcriptions",
			"Up to 3 Posts stored",
			"Markdown support",
			"Community support",
			"AI powered suggestions",
		],
		btn: {
			text: "Start Your Free Trial",
			href: "#",
		},
	},
	{
		highlighted: true,
		name: "Pro",
		info: "For small businesses",
		price: {
			monthly: 17,
			yearly: 14,
		},
		features: [
			"Up to 500 Blog Posts",
			"Up to 500 Transcriptions",
			"Up to 500 Posts stored",
			"Unlimited Markdown support",
			"SEO optimization tools",
			"Priority support",
			"AI powered suggestions",
		],
		btn: {
			text: "Get started",
			href: "#",
		},
	},
	{
		name: "Business",
		info: "For large organizations",
		price: {
			monthly: 49,
			yearly: 40,
		},
		features: [
			"Unlimited Blog Posts",
			"Unlimited Transcriptions",
			"Unlimited Posts stored",
			"Unlimited Markdown support",
			"SEO optimization tools",
			"Priority support",
			"AI powered suggestions",
		],
		btn: {
			text: "Contact team",
			href: "#",
		},
	},
];

export function PricingSection() {
	const [frequency, setFrequency] = React.useState<"monthly" | "yearly">(
		"monthly"
	);

	return (
		<div className="flex w-full flex-col items-center justify-center space-y-7 p-4">
			<div className="mx-auto max-w-xl space-y-2">
				<h2 className="font-heading text-center font-bold text-2xl tracking-tight md:text-3xl lg:font-extrabold lg:text-4xl">
					Plans that Scale with You
				</h2>
				<p className="text-center text-muted-foreground text-sm md:text-base">
					Whether you&apos;re just starting out or growing fast, our flexible pricing
					has you covered: with no hidden costs.
				</p>
			</div>

			<FrequencyToggle frequency={frequency} setFrequency={setFrequency} />
			<div className="mx-auto grid w-full max-w-4xl grid-cols-1 gap-6 md:grid-cols-3">
				{plans.map((plan) => (
					<PricingCard frequency={frequency} key={plan.name} plan={plan} />
				))}
			</div>
		</div>
	);
}

type PricingCardProps = React.ComponentProps<"div"> & {
	plan: Plan;
	frequency?: FREQUENCY;
};

export function PricingCard({
	plan,
	className,
	frequency = "monthly",
	...props
}: PricingCardProps) {
	return (
		<div
			className={cn(
				"relative flex w-full flex-col overflow-hidden rounded-lg border shadow-xs",
				plan.highlighted && "scale-105",
				className
			)}
			key={plan.name}
			{...props}
		>
			<div
				className={cn(
					"border-b p-4",
					plan.highlighted && "bg-card dark:bg-card/80"
				)}
			>
				<AnimatePresence mode="wait">
					<div className="absolute top-2 right-2 z-10 flex items-center gap-2">
						{plan.highlighted && (
							<motion.div
								className="flex items-center gap-1 rounded-md border bg-background px-2 py-0.5 text-xs"
								key="popular-badge"
								layout
								transition={{ duration: 0.1 }}
							>
								<StarIcon className="size-3 fill-current" />
								Popular
							</motion.div>
						)}

						{frequency === "yearly" &&
							plan.price.monthly > plan.price.yearly && (
								<motion.div
									animate={{ opacity: 1 }}
									className="flex items-center gap-1 rounded-md border bg-primary px-2 py-0.5 text-primary-foreground text-xs"
									exit={{ opacity: 0 }}
									initial={{ opacity: 0 }}
									key="discount-badge"
									layout
									transition={{ duration: 0.15 }}
								>
									{/* Calculate the actual discount percentage of the plan */}
									{Math.round(
										((plan.price.monthly - plan.price.yearly) /
											plan.price.monthly) *
											100
									)}
									% off
								</motion.div>
							)}
					</div>
				</AnimatePresence>

				<div className="font-medium text-lg">{plan.name}</div>
				<p className="font-normal text-muted-foreground text-sm">{plan.info}</p>
				<h3 className="font-heading mt-6 mb-1 flex w-max items-end gap-1">
					<NumberFlow
						className="font-extrabold text-3xl [&::part(suffix)]:font-normal [&::part(suffix)]:text-base [&::part(suffix)]:text-muted-foreground"
						format={{
							style: "currency",
							currency: "USD",
							notation: "compact",
						}}
						suffix="/month"
						value={plan.price[frequency]}
					/>
				</h3>
				<p className="mb-2 font-normal text-muted-foreground text-xs">
					billed {frequency}
				</p>
			</div>
			<div
				className={cn(
					"space-y-3 px-4 pt-6 pb-8 text-muted-foreground text-sm",
					plan.highlighted && "bg-muted/10"
				)}
			>
				{plan.features.map((feature) => (
					<div className="flex items-center gap-2" key={feature}>
						<CheckCircleIcon className="size-3.5 text-foreground" />
						<p>{feature}</p>
					</div>
				))}
			</div>
			<div
				className={cn(
					"mt-auto w-full border-t p-3",
					plan.highlighted && "bg-card dark:bg-card/80"
				)}
			>
				<Button
					asChild
					className="w-full"
					variant={plan.highlighted ? "default" : "outline"}
				>
					<a href={plan.btn.href}>{plan.btn.text}</a>
				</Button>
			</div>
		</div>
	);
}

"use client";

import { cn } from "@/lib/utils";
import { motion, useReducedMotion } from "motion/react";
import {
	type ComponentProps,
	type Dispatch,
	type SetStateAction,
	useCallback,
	useLayoutEffect,
	useRef,
	useState,
} from "react";

export type FREQUENCY = "monthly" | "yearly";

const defaultFrequencies: FREQUENCY[] = ["monthly", "yearly"];

type FrequencyToggleProps = ComponentProps<"fieldset"> & {
	frequency: FREQUENCY;
	setFrequency: Dispatch<SetStateAction<FREQUENCY>>;
	frequencies?: FREQUENCY[];
};

type CursorPosition = {
	left: number;
	top: number;
	width: number;
	height: number;
	opacity: number;
};

function measure(el: HTMLButtonElement): CursorPosition {
	return {
		left: el.offsetLeft,
		top: el.offsetTop,
		width: el.offsetWidth,
		height: el.offsetHeight,
		opacity: 1,
	};
}

export function FrequencyToggle({
	frequency,
	setFrequency,
	frequencies = defaultFrequencies,
	className,
	...props
}: FrequencyToggleProps) {
	const reduceMotion = useReducedMotion();
	const tabsRef = useRef<Partial<Record<FREQUENCY, HTMLButtonElement>>>({});
	const [position, setPosition] = useState<CursorPosition>({
		left: 0,
		top: 0,
		width: 0,
		height: 0,
		opacity: 0,
	});

	const moveTo = useCallback((value: FREQUENCY) => {
		const tab = tabsRef.current[value];
		if (!tab) {
			return;
		}
		setPosition(measure(tab));
	}, []);

	useLayoutEffect(() => {
		moveTo(frequency);
	}, [frequency, moveTo]);

	return (
		<fieldset
			className={cn(
				"relative mx-auto flex w-fit rounded-lg border bg-card p-1 shadow-xs",
				className
			)}
			{...props}
			aria-label="Frequency"
		>
			{frequencies.map((freq) => (
				<button
					aria-pressed={frequency === freq}
					className="relative z-10 px-4 py-1 text-sm capitalize"
					key={freq}
					onClick={() => setFrequency(freq)}
					ref={(el) => {
						if (el) {
							tabsRef.current[freq] = el;
						}
					}}
					type="button"
				>
					{freq}
				</button>
			))}
			<motion.span
				animate={{
					left: position.left,
					width: position.width,
					opacity: position.opacity,
				}}
				aria-hidden
				className="pointer-events-none absolute z-10 rounded-md bg-background mix-blend-difference dark:bg-foreground"
				initial={false}
				style={{ top: position.top, height: position.height }}
				transition={
					reduceMotion ? { duration: 0 } : { type: "spring", duration: 0.4 }
				}
			/>
		</fieldset>
	);
}
